import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            A = next(iterator)
            B = next(iterator)
        except StopIteration:
            break

        n = len(A)
        if n == 0:
            results.append("0")
            continue

        target = (B + B)[:2 * n - 1]

        count = 0
        for i in range(n):
            match = True
            for j in range(n):
                if A[j] != target[i + j]:
                    match = False
                    break
            if match:
                count += 1

        results.append(str(count))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
